// === PREFIX SUM TEMPLATE ===
function buildPrefix(arr) {
  const n = arr.length;
  const pre = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    pre[i + 1] = pre[i] + arr[i];
  }
  return pre;
}
// Range sum [l, r] inclusive, 0-indexed:
// pre[r + 1] - pre[l]

// === KADANE'S ALGORITHM ===
function maxSubarray(arr) {
  let maxHere = arr[0];
  let maxTotal = arr[0];
  for (let i = 1; i < arr.length; i++) {
    // extend previous subarray or start fresh at current element
    maxHere = Math.max(arr[i], maxHere + arr[i]);
    maxTotal = Math.max(maxTotal, maxHere);
  }
  return maxTotal;
}

// === WRITE POINTER (IN-PLACE FILTER) ===
function removeDuplicatesSorted(arr) {
  if (!arr.length) return 0;
  let write = 1;
  for (let i = 1; i < arr.length; i++) {
    // only write when element is new
    if (arr[i] !== arr[i - 1]) arr[write++] = arr[i];
  }
  return write; // valid length
}
